describe('ChatOrchestrator onError coercion', () => {
  const inspectTurn = async (thrown: unknown) => {
    const seen: Error[] = [];
    const orchestrator = createChatOrchestrator(createErrorProvider(thrown), promptBuilder, undefined, {
      hooks: {onError: async (_session, error) => void seen.push(error)},
    });
    const turn = orchestrator.processMessage(createSession('hello'));
    const callerRejection = await turn.then(
      () => Symbol('resolved'),
      (caught: unknown) => caught
    );
    const reported = seen[0];
    return {
      calls: seen.length,
      isError: reported instanceof Error,
      sameInstance: Object.is(reported, thrown),
      hasCause: reported instanceof Error ? 'cause' in reported : false,
      cause: reported?.cause,
      message: reported?.message,
      callerReceivedSame: Object.is(callerRejection, thrown),
    };
  };

  it('wraps thrown primitives and objects in an Error with cause while passing Error instances through and rethrowing the original', async () => {
    const existing = new Error('already an error');
    const payload = {code: 503, detail: 'upstream down'};

    const outcomes = {
      errorInstance: await inspectTurn(existing),
      text: await inspectTurn('plain string boom'),
      plainObject: await inspectTurn(payload),
      missing: await inspectTurn(undefined),
    };

    expect(outcomes).toEqual({
      errorInstance: {
        calls: 1,
        isError: true,
        sameInstance: true,
        hasCause: false,
        cause: undefined,
        message: 'already an error',
        callerReceivedSame: true,
      },
      text: {
        calls: 1,
        isError: true,
        sameInstance: false,
        hasCause: true,
        cause: 'plain string boom',
        message: 'plain string boom',
        callerReceivedSame: true,
      },
      plainObject: {
        calls: 1,
        isError: true,
        sameInstance: false,
        hasCause: true,
        cause: payload,
        message: expect.stringContaining('upstream down'),
        callerReceivedSame: true,
      },
      missing: {
        calls: 1,
        isError: true,
        sameInstance: false,
        hasCause: true,
        cause: undefined,
        message: 'undefined',
        callerReceivedSame: true,
      },
    });
  });
});

