// Preserves the raw rejection on `cause` while satisfying hooks typed against `Error`.
function coerceToError(thrown: unknown): Error {
  if (thrown instanceof Error) return thrown;
  return new Error(typeof thrown === 'string' ? thrown : inspect(thrown), {cause: thrown});
}

